var promise=when.resolve(result);
me.activeASO ="AsoPortfolio";

/* Convertir datos de cobertura @VictorBosio */
me.getAllItems().forEach(e => {
  if(e.getCoverage().includes('rojo')){
      e.setCoverageImage('MyRedCoverage');
  }
  if(e.getCoverage().includes('gris')){
      e.setCoverageImage('MyGreyCoverage');
  }
  if(e.getCoverage().includes('verde')){
      e.setCoverageImage('MyGreenCoverage');
  }
  if(e.getCoverage().includes('amarillo')){
      e.setCoverageImage('MyYellowCoverage');
  }
  if(e.getCoverage().includes('azul')){
      e.setCoverageImage('MyBlueCoverage');
  }
});
